import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand


class SetMmeTimer(GenericEPCSIMCommand):
    """SetMmeTimer command class."""

    def __init__(self, connection, name, value, prompt=None, newline_chars=None, runner=None):
        """
         Setmmetimer command set value of equivalent timer.

        :param name: name of timer
        :param value: value of timer
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        :param connection: moler connection to device, terminal when command is executed.
        """
        super(SetMmeTimer, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.value = value
        self.name = name
        self.current_ret["RESULT"] = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "set_mme_timer"
        cmd = f"{cmd} {self.name}"
        cmd = f"{cmd}={self.value}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Summary line.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error_header(line)

            except ParsingDone:
                pass
        return super(SetMmeTimer, self).on_new_line(line, is_full_line)

    # Error: mme_timer: Unexpected argument 1: 'T3450=60000'
    _re_check_error = re.compile(r"^Error:\s\w+:\s(?P<ERROR>.+')")

    def _parse_error_header(self, line):
        if self._regex_helper.search(SetMmeTimer._re_check_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')} "))

            raise ParsingDone


COMMAND_OUTPUT = """EGATE> set_mme_timer T3452=60000
EGATE> """

COMMAND_KWARGS = {"name": "T3452", "value": "60000"}

COMMAND_RESULT = {"RESULT": {}}
